function category(r){if(r.category)return r.category;if(r.kind!=='package')return kindNames[r.kind]||'待分类';const n=r.name||'';for(const [re,v] of [[/喷雾泵|乳液泵|泵头|喷头|泡沫泵/,'泵头与喷头'],[/滴管/,'滴管与滴管瓶'],[/软管/,'软管'],[/袋|膜袋/,'袋类'],[/彩盒|纸盒|包装盒|礼盒|内托/,'外包装'],[/瓶/,'瓶类'],[/罐|膏霜盒/,'罐与广口盒'],[/盖|内塞|垫片/,'盖与其他配件'],[/标签|标贴/,'标签辅材']])if(re.test(n))return v;return '待细分';}
