function galleryImages(r){const seen=new Set();return (r.images||[]).filter(i=>{const path=typeof i==='string'?i:i?.path||i?.file;if(!path||i.missing)return false;const key=imagePath(i);if(seen.has(key))return false;seen.add(key);return true;});}
