document.addEventListener('error',e=>{const el=e.target;if(!el.matches?.('img[data-gallery-record]'))return;const r=records.find(r=>r.id===el.dataset.galleryRecord);if(!r)return;const failed=new Set(JSON.parse(el.dataset.failedImages||'[]'));failed.add(el.getAttribute('src'));const next=galleryImages(r).find(i=>!failed.has(imagePath(i)));if(next){el.dataset.failedImages=JSON.stringify([...failed]);el.src=imagePath(next);const label=el.parentElement.querySelector('.image-label');if(label)label.textContent=imageLabel(next,r);if(el.parentElement.id==='detailPhoto')$('#originalImageLink').href=imagePath(next);}else{el.hidden=true;el.parentElement.querySelector('.image-label').textContent='图片暂未加载，请刷新重试';}},true);
