    if(!jpeg&&!png&&!webp)throw Error('暂支持 JPEG、PNG、WebP 图片，请转换格式后重试。');
    const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('无法读取图片文件，请重新选择。'));reader.readAsDataURL(file);});
