function imageCropPoint(e){const c=$('#imageCropCanvas'),box=c.getBoundingClientRect();return {x:Math.max(0,Math.min(c.width,(e.clientX-box.left)*c.width/box.width)),y:Math.max(0,Math.min(c.height,(e.clientY-box.top)*c.height/box.height))};}
