function updateCatalogPage(value,{size=state.pageSize,focus='current'}={}){const input=String(value??'').trim();if(!/^\d+$/.test(input)||!Number.isSafeInteger(Number(input))){toast('请输入有效的整数页码');$('#pageJump')?.focus({preventScroll:true});return;}if(!pageSizes.includes(size))return;const a=filtered(),total=Math.max(1,Math.ceil(a.length/size)),page=Math.max(1,Math.min(Number(input),total)),oldPage=state.page,oldSize=state.pageSize,region=$('#catalogResults');if(!region)return;const headerOffset=(document.querySelector('header')?.getBoundingClientRect().height||0)+20,scrollTop=window.scrollY+region.getBoundingClientRect().top-headerOffset,shouldScroll=region.getBoundingClientRect().top<headerOffset;if(Number(input)!==page)toast(`页码已调整到第 ${page} 页`);if(oldPage===page&&oldSize===size){if($('#pageJump'))$('#pageJump').value=page;return;}state.pageSize=size;state.page=page;region.innerHTML=catalogResults(a);setupReveal();const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;if(!reduced){const content=$('#catalogPageContent');content.classList.add('page-enter');content.style.setProperty('--page-shift',page<oldPage?'-7px':'7px');}const target=focus==='size'?$('#pageSize'):focus==='jump'?$('#pageJump'):region.querySelector(`[data-page-control="${focus}"]:not(:disabled)`)||region.querySelector('[aria-current="page"]');target?.focus({preventScroll:true});if(shouldScroll)window.scrollTo({top:Math.max(0,scrollTop),behavior:reduced?'auto':'smooth'});}

function catalogView(){const all=records.filter(r=>r.kind==='package'),withPics=all.filter(r=>primaryImage(r)),a=filtered(),page=Math.max(1,Math.min(state.page,Math.ceil(a.length/state.pageSize)||1));state.page=page;const categories=[...new Set(records.map(r=>r._category))].sort();const scope=records;const mats=[...new Set(scope.flatMap(r=>r._materials))].sort();const capCounts=new Map();for(const r of records.filter(r=>r.kind==='package'))for(const v of r._capacities)capCounts.set(v,(capCounts.get(v)||0)+1);const caps=[...capCounts.keys()].filter(v=>v>0).sort((a,b)=>a-b);return showroomHero()+title(state.view==='favorites'?'我的收藏':esc(catalog.settings?.catalogTitle||'包材选型库'),esc(catalog.settings?.catalogSubtitle||'从原始询价资料中查找包材，保留图片、报价条件与来源。'),'<button class="btn" data-action="export">导出当前列表</button>')+(catalog.settings?.announcement?`<div class="note" style="margin-bottom:16px" data-i18n-skip>${esc(catalog.settings.announcement)}</div>`:'')+`<div class="stats"><div class="stat"><span>产品来源条目</span><strong>${all.length}</strong><small>按来源和规格保留</small></div><div class="stat"><span>材质标签</span><strong>${new Set(all.flatMap(r=>r._materials)).size}</strong><small>按原始资料整理</small></div><div class="stat"><span>附报价原文</span><strong>${all.filter(r=>quote(r)).length}</strong><small>使用前复核</small></div><div class="stat"><span>产品来源</span><strong>${new Set(all.map(r=>r._sourceFile).filter(Boolean)).size}</strong><small>图册与询价表</small></div></div><section class="filters" aria-label="检索条件"><form id="searchForm"><div class="search-row"><div class="search-box"><span>⌕</span><input id="query" name="query" aria-label="检索包材" placeholder="搜索产品编号（如 YZ-BC-000001）、名称、材质或规格" value="${esc(state.query)}"></div><button class="btn primary" type="submit">搜索</button><button class="btn image-search-launch" type="button" data-image-search="open">上传图片找相似</button><button class="btn" type="button" data-action="reset">重置</button></div></form><p id="imageSearchScope" class="image-search-scope">${esc(imageSearchScope())}</p>${imageSearchContext()}<p class="filter-help">筛选项均可多选：同一项满足任一条件，不同项同时满足。用途依据已有名称和用途资料整理，未明确用途的包材可在全部资料中查找。</p><div class="filter-grid">${multiFilter('kind','资料类型',Object.entries(kindNames),'全部资料')}${multiFilter('section','包材分区',Object.entries(sectionNames),'不限分区')}${multiFilter('category','包材类型',categories,'全部类型')}${multiFilter('material','材质',mats,'不限材质')}${multiFilter('capacity','容量',caps.map(v=>[String(v),v+' mL']),'不限容量')}${multiFilter('bottle','瓶型',[...new Set(records.map(r=>r.bottleType).filter(Boolean))].sort(),'不限瓶型')}${multiFilter('use','用途',usageOptions(records),'不限用途')}${multiFilter('quote','报价资料',[['yes','有报价原文'],['no','待补报价']],'全部状态')}${multiFilter('imageStatus','图片状态',Object.entries(imageStatusNames),'全部图片状态')}${multiFilter('source','来源图册',[...new Set(records.map(r=>r._sourceFile).filter(Boolean))].sort(),'全部来源')}</div>${activeFilters()}</section><section id="catalogResults" aria-label="筛选结果">${catalogResults(a)}</section>${selectionBar()}`;}
function card(r){return `<article class="card ${r.kind==='source_page'?'source-card':''}"><button class="photo" data-detail="${esc(r.id)}" aria-label="查看${esc(r.name)}">${image(r)}</button><div class="card-body"><span class="record-code" data-record-id="${esc(r.id)}" data-product-code="${esc(r.productCode||'')}">${r.productCode?'产品编号 · ':'来源编号 · '}${esc(productLabel(r))}</span><button class="card-title" data-detail="${esc(r.id)}">${sourceText(r.name,'名称待补')}</button><div class="tags"><span class="tag blue">${esc(r._category)}</span>${r.provenance?.extraction==='ocr'?'<span class="tag orange">OCR待核对</span>':''}${r._materials.slice(0,2).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}${r._capacities.slice(0,3).map(x=>`<span class="tag">${x}mL</span>`).join('')}</div><div class="quote-preview" data-i18n-skip>${esc(r.kind==='source_page'?'原页图片与识别文字，具体产品待核对':r.kind==='process_rule'?(quote(r)||'通用参考规则，未绑定具体产品'):(quote(r)||'报价待补'))}</div><span class="muted" style="font-size:12px" data-i18n-skip>${esc((r.kind==='source_page'?r._sourceFile:supplier(r)).slice(0,70))}</span></div><div class="card-foot"><label class="select-label"><input type="checkbox" data-select="${esc(r.id)}" ${state.selected.includes(r.id)?'checked':''}>加入对比</label><button class="favorite ${prefs.favorites.includes(r.id)?'on':''}" aria-label="${prefs.favorites.includes(r.id)?'取消收藏':'收藏'}${esc(r.name)}" data-favorite="${esc(r.id)}">${prefs.favorites.includes(r.id)?'★':'☆'}</button></div></article>`;}
function table(a){return `<div class="panel table-wrap"><table><thead><tr><th>选择</th><th>产品编号／名称与来源</th><th>类型／材质</th><th>报价原文</th><th>供应商</th><th></th></tr></thead><tbody>${a.map(r=>`<tr><td><input aria-label="选择${esc(r.name)}" type="checkbox" data-select="${esc(r.id)}" ${state.selected.includes(r.id)?'checked':''}></td><td><div class="record-code">${esc(productLabel(r))}</div><button class="quiet" data-detail="${esc(r.id)}"><span data-i18n-skip>${esc(r.name)}</span></button><div class="source-line">${esc(source(r))}</div></td><td>${esc(r._category)}<br>${esc(r._materials.join(' / ')||'待补')}</td><td class="raw" style="max-width:320px">${esc(quote(r)||'待询价')}</td><td data-i18n-skip>${esc(supplier(r))}</td><td><button class="quiet" data-detail="${esc(r.id)}">详情</button></td></tr>`).join('')}</tbody></table></div>`;}
function selectionBar(){return state.selected.length?`<div class="selection-bar"><span>已选 <b>${state.selected.length}</b> 项</span><div><button class="btn" data-action="clear-selected">清空</button><button class="btn" data-action="save-plan">保存方案</button><button class="btn primary" data-action="compare">查看对比</button></div></div>`:'';}
function modal(title,body,foot=''){const d=$('#modal');$('#modalBody').innerHTML=`<div class="dialog-head"><h2${records.some(r=>r.name===title)||plans.some(p=>p.title===title)?' data-i18n-skip':''}>${esc(title)}</h2><button class="close" data-close aria-label="关闭对话框">×</button></div><div class="dialog-content">${body}</div>${foot?`<div class="dialog-foot">${foot}</div>`:''}`;if(!d.open)d.showModal();}
function facts(rows){return `<dl class="facts">${rows.map(([k,v])=>`<div class="fact"><dt>${esc(k)}</dt><dd>${v?(['材质','瓶型','用途','类别','类型'].includes(k)?esc(text(v)):`<span data-i18n-skip>${esc(text(v))}</span>`):'待补'}</dd></div>`).join('')}</dl>`;}
function linkedProducts(r){if(r.kind!=='source_page'||!Array.isArray(r.rawCells?.linkedRecordIds))return '';const ids=new Set(r.rawCells.linkedRecordIds),linked=records.filter(item=>ids.has(item.id));return linked.length?`<div class="section-label">本页已整理产品（${linked.length}）</div><div class="linked-products">${linked.map(item=>`<button class="btn small" data-detail="${esc(item.id)}"><span data-i18n-skip>${esc(item.name||item.id)}</span></button>`).join('')}</div>`:'<p class="note">本页暂无可展示的独立产品记录，可先参考原图并核对型号与规格。</p>';}
function meaningful(value){const v=text(value).trim();return /^(?:[/／—–-]+|暂无|无|待补|待确认|未填写|未注明)$/.test(v)?'':v;}
function specificationDetails(r){
  const seenDetails=new Set();const allRows=(r.productDetails||[]).filter(d=>{if(!d?.label||!meaningful(d.value))return false;const key=d.label+'|'+d.value;if(seenDetails.has(key))return false;seenDetails.add(key);return true;});
  const pricedLabels=new Set(['历史工艺费用及条件','税运条件','打样费用及退款条件','裸瓶报价','泵头报价','瓶身报价','模具费用及条件','内塞报价','盖子报价','旋盖报价']);
  const rows=allRows.filter(d=>!pricedLabels.has(d.label));
  const evidence=allRows.filter(d=>d.evidence);
  return `<section class="product-specs"><h3 class="spec-section-title">产品细则</h3>${facts([['产品编号',r.productCode],['型号',r.model],['材质',(r.materials||[]).join(' / ')],['标称容量',r.capacityMl==null?'':r.capacityMl+' mL'],['瓶型',r.bottleType],['系列',r.series],['用途',(r._uses||r.uses||[]).join(' / ')],['产品说明',r.description]])}${rows.length?`<h3 class="spec-section-title">补充规格</h3><dl class="spec-detail-grid">${rows.map(d=>`<div><dt>${esc(d.label)}</dt><dd><span data-i18n-skip>${esc(d.value)}</span></dd></div>`).join('')}</dl>`:''}<p class="spec-price-note">历史询价资料，使用前请复核数量、税运与报价有效期。</p>${facts([['供应商',r.supplierRaw],['联系方式',r.contactRaw]])}${evidence.length?`<details class="source-disclosure"><summary>查看细则整理依据</summary>${evidence.map(d=>`<div class="spec-evidence"><strong>${esc(d.label)}</strong><p class="raw"><span data-i18n-skip>${esc(d.evidence)}</span></p></div>`).join('')}</details>`:''}</section>`;
}
function detail(id){
  const r=records.find(r=>r.id===id);if(!r)return;const shown=galleryImage(r);
  const nonPackageFacts=facts([['资料编号',r.id],['系列',r.series],['型号',r.model],['瓶型',r.bottleType],['材质',(r.materials||[]).join(' / ')],['标称容量',r.capacityMl==null?'':r.capacityMl+' mL'],['用途',(r._uses||r.uses||[]).join(' / ')],['产品说明',r.description],['供应商',r.supplierRaw],['联系方式',r.contactRaw]]);
  const original=`${facts([['材料原文',r.materialRaw],['规格原文',r.specificationRaw],['供应商地址',r.addressRaw],['工艺原文',r.processRaw]])}${quoteDetails(r)}${extraDetails(r)}`;
  modal(r.name||'询价记录',`<div class="detail-grid"><div class="detail-visual"><div class="detail-photo" id="detailPhoto">${image(r)}</div><a id="originalImageLink" class="quiet original-image-link" ${shown?`href="${esc(imagePath(shown))}"`:'hidden'} target="_blank" rel="noopener">查看当前原图 ↗</a>${imageThumbnails(r)}<div class="source-line">${esc(source(r))}<br><span data-i18n-skip>${esc(r.id)}</span></div></div><div><div class="tags"><span class="tag blue">${esc(kindNames[r.kind]||'待分类')}</span><span class="tag orange">${esc(r.kind==='source_page'?'原页线索 · 请对照型号与规格':r.provenance?.extraction==='ocr'?'OCR 提取 · 待人工核对':r.kind==='process_rule'?'独立参考规则':'历史资料 · 有效性待复核')}</span></div>${renderPricing(r)}${r.kind==='package'?specificationDetails(r):nonPackageFacts+original}${r.kind==='package'?`<details class="source-disclosure"><summary>原始参数与完整报价</summary>${original}</details>`:''}${catalog.settings?.processReference?`<details class="source-disclosure"><summary>工艺参考标准</summary><div class="note raw">${esc(catalog.settings.processReference)}<br>由业务员结合工艺判断起订量、货期与最终价格。</div></details>`:''}${r.uncertainties?.length?`<details class="source-disclosure"><summary>待确认事项</summary><div class="note" data-i18n-skip>${esc(r.uncertainties.map(text).join('；'))}</div></details>`:''}${linkedProducts(r)}<div class="detail-actions"><button class="btn" data-favorite="${esc(r.id)}">${prefs.favorites.includes(r.id)?'取消收藏':'收藏此记录'}</button>${session.role==='admin'?`<a class="btn primary" href="/admin#records/${encodeURIComponent(r.id)}">编辑资料</a>`:''}</div></div></div><details class="source-disclosure"><summary>查看原始来源字段</summary><div class="table-wrap"><table><tbody>${Object.entries(r.rawCells||{}).map(([k,v])=>`<tr><th>${esc(k)}</th><td class="raw">${esc(text(v))}</td></tr>`).join('')}</tbody></table></div></details>`);
}
function compare(){if(state.selected.length<2)return toast('至少选择2条记录进行对比');const a=state.selected.map(id=>records.find(r=>r.id===id));const rows=[['图片',r=>image(r)],['名称',r=>esc(r.name)],['类型',r=>esc(r._category)],['规格原文',r=>esc(text(r.specificationRaw)||'待补')],['材料原文',r=>esc(text(r.materialRaw)||'待补')],['供应商',r=>esc(supplier(r))],['报价口径',r=>esc(text(r.quoteHeader)||'未注明')],['确认单价',r=>esc(r.unitPrice==null?'待确认':String(r.unitPrice)+(r.currency?' '+r.currency:''))],['普通报价',r=>esc(text(r.quoteRaw)||'待询价')],['普通起订／数量',r=>esc(text(r.moqRaw)||'待补')],['普通交期',r=>esc(text(r.leadTimeRaw)||'待补')],['定制报价',r=>esc(text(r.customQuoteRaw)||'待询价')],['定制起订／数量',r=>esc(text(r.customMoqRaw)||'待补')],['定制交期',r=>esc(text(r.customLeadTimeRaw)||'待补')],['样品费',r=>esc(text(r.sampleFeeRaw)||'待补')],['开模费',r=>esc(text(r.moldFeeRaw)||'待补')],['来源',r=>esc(source(r))]];modal('包材与询价对比',`<div class="note">不同数量、币种、税运条件与套装范围的报价不能直接比低价。以下完整保留各条原文。</div><div class="table-wrap" style="margin-top:18px"><table class="compare-grid"><tbody>${rows.map(([k,fn])=>`<tr><th>${k}</th>${a.map(r=>`<td${['图片','类型'].includes(k)?'':' data-i18n-skip'}>${fn(r)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`,`<button class="btn primary" data-action="save-plan">保存为选型方案</button>`);}
function plansView(){return title('选型方案','保存当时选中的记录与报价原文，后续资料更新不覆盖原方案。')+(plans.length?plans.map(p=>`<section class="panel"><div class="panel-title"><div><h2><span data-i18n-skip>${esc(p.title)}</span></h2><p class="sub">${esc(p.id)} · ${esc(p.created.slice(0,10))} · ${p.snapshot.length}项</p></div><button class="btn small" data-plan="${esc(p.id)}">查看快照</button></div><div class="raw">${sourceText(p.note,'未填写项目说明')}</div></section>`).join(''):'<div class="empty">还没有选型方案。在图库中勾选候选包材，然后选择“保存方案”。</div>');}
function samplesView(){const rows=sampleData.samples;return title('实物样品借还','只登记实际收到的样品；原表询价记录不代表公司已持有实物。')+`<div class="note" style="margin-bottom:20px">管理员从包材详情登记实物样品并维护编号和位置。借出与归还、测试耗用、寄给客户分别记账。</div>${rows.length?`<section class="panel table-wrap"><table><thead><tr><th>实物编号／包材</th><th>当前所在</th><th>状态</th><th>借用人／归还日期</th><th>操作</th></tr></thead><tbody>${rows.map(s=>`<tr><td><b><span data-i18n-skip>${esc(s.id)}</span></b><div class="sub"><span data-i18n-skip>${esc(records.find(r=>r.id===s.record_id)?.name||s.record_id)}</span></div></td><td><span data-i18n-skip>${esc(s.location)}</span><div class="sub"><span data-i18n-skip>${esc(s.condition)}</span></div></td><td><span class="tag ${s.status==='available'?'green':'orange'}">${esc(statusNames[s.status]||s.status)}</span></td><td>${sourceText(s.borrower,'—')}<br>${esc(s.due||'—')}${s.status==='lent'&&s.due<new Date().toLocaleDateString('sv-SE')?'<span class="tag orange">已逾期</span>':''}</td><td>${session.role==='admin'&&s.status==='available'?`<button class="quiet" data-sample="${esc(s.id)}" data-op="lend">借出</button>`:''}${session.role==='admin'&&s.status==='lent'?`<button class="quiet" data-sample="${esc(s.id)}" data-op="return">归还</button>`:''}${session.role==='admin'&&['available','lent'].includes(s.status)?`<button class="quiet" data-sample="${esc(s.id)}" data-op="consumed">耗用</button><button class="quiet" data-sample="${esc(s.id)}" data-op="sent">寄出</button>`:''}<button class="quiet" data-history="${esc(s.id)}">记录</button></td></tr>`).join('')}</tbody></table></section>`:'<div class="empty">尚未登记实物样品。没有从询价表自动生成库存。</div>'}`;}
function sourcesView(){const counts=new Map();for(const r of records){const name=r._sourceFile;if(!name)continue;let item=counts.get(name);if(!item){item={product:0,pages:0,rules:0};counts.set(name,item);}if(r.kind==='package')item.product++;else if(r.kind==='source_page')item.pages++;else if(r.kind==='process_rule')item.rules++;}const kinds=Object.entries(kindNames).map(([k,n])=>[n,records.filter(r=>r.kind===k).length]);return title('素材与导入概况','原始来源分开登记，图册页线索与产品条目分别计数。')+`<div class="panel"><h2>当前资料</h2>${facts([['在线记录',String(records.length)],['产品来源条目',String(records.filter(r=>r.kind==='package').length)],['图册与图片线索',String(records.filter(r=>r.kind==='source_page').length)],['独立工艺与价格参考',String(records.filter(r=>r.kind==='process_rule').length)],['实物库存','仅以实际登记为准']])}<div class="note">新图册记录包含OCR提取线索，显示来源和待核对提示。缺失参数保持空白；整页预览不是单品图。历史报价使用前应复核数量、税运、币种和有效期。</div></div><div class="panel table-wrap"><h2>来源文件</h2><table><thead><tr><th>来源</th><th>产品条目</th><th>图页／图片线索</th><th>独立参考规则</th></tr></thead><tbody>${[...counts].sort((a,b)=>a[0].localeCompare(b[0],'zh')).map(([name,v])=>`<tr><td data-i18n-skip>${esc(name)}</td><td>${v.product}</td><td>${v.pages}</td><td>${v.rules}</td></tr>`).join('')}</tbody></table></div><div class="panel"><h2>分类方式</h2><p class="sub">左侧按包材类型、材质、容量区间和来源组合筛选；顶部可继续筛选精确容量、瓶型和报价资料。每个明确规格独立一条，未拆开的图片与图册页在“图册与图片线索”中查看。</p><p class="sub">印刷工艺价格作为独立参考规则保留，不自动套到产品上；业务员结合客户要求判断起订量、货期和最终报价。</p></div>`;}
function inputField(label,name,type='text',value='',required=true){return `<label class="field">${label}${required?' *':''}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;}
function sampleForm(id,op){const s=sampleData.samples.find(v=>v.id===id);if(!s)return;const title={lend:'登记借出',return:'登记归还',consumed:'登记测试耗用',sent:'登记寄给客户'}[op];let fields=op==='lend'?inputField('借用人','borrower')+inputField('预计归还日期','due','date'):op==='return'?inputField('归还位置','location')+inputField('样品状况','condition'):'';fields+=`<label class="field full">${['consumed','sent'].includes(op)?'用途或去向 *':'备注'}<textarea name="note" ${['consumed','sent'].includes(op)?'required':''}></textarea></label>`;modal(title,`<p class="sub">${esc(id)}</p><form id="sampleActionForm" data-id="${esc(id)}" data-op="${op}"><div class="form-grid">${fields}</div><p class="form-error" role="alert"></p><div class="dialog-foot"><button class="btn" type="button" data-close>取消</button><button class="btn primary">确认登记</button></div></form>`);}
function exportRows(rows){const escape=v=>csvCell(text(v));const cells=[['产品编号','内部记录ID','名称','类型','材料原文','规格原文','供应商原文','报价口径','普通报价原文','普通起订数量','普通交期','定制报价原文','定制起订数量','定制交期','样品费原文','开模费原文','来源'],...rows.map(r=>[r.productCode||'',r.id,r.name,kindNames[r.kind],r.materialRaw,r.specificationRaw,r.supplierRaw,r.quoteHeader,r.quoteRaw,r.moqRaw,r.leadTimeRaw,r.customQuoteRaw,r.customMoqRaw,r.customLeadTimeRaw,r.sampleFeeRaw,r.moldFeeRaw,source(r)])];const blob=new Blob(['\ufeff'+cells.map(row=>row.map(escape).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='源泽包材-内部选型列表.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;try{if(b.dataset.clearFacet){state[b.dataset.clearFacet]=[];state.page=1;refreshFacet(b.dataset.clearFacet);}
else if(b.dataset.clearFilter){const key=b.dataset.clearFilter;if(facetKeys.includes(key)){state[key]=picked(key).filter(v=>v!==b.dataset.filterValue);state.page=1;render();}}
else if(b.dataset.section){beginProductFacet();toggleFacet('section',b.dataset.section);render();$('#searchForm')?.scrollIntoView({behavior:reduceMotion?.matches?'auto':'smooth',block:'start'});}
else if(b.dataset.sideKind!==undefined){state.view='catalog';toggleFacet('kind',b.dataset.sideKind);render();}
else if(b.dataset.sideCategory!==undefined){beginProductFacet();toggleFacet('category',b.dataset.sideCategory);render();}
else if(b.dataset.sideMaterial!==undefined){beginProductFacet();toggleFacet('material',b.dataset.sideMaterial);render();}
else if(b.dataset.sideCapacity!==undefined){beginProductFacet();toggleFacet('capacityBand',b.dataset.sideCapacity);state.capacity=[];render();}
else if(b.dataset.sideSource!==undefined){state.view='catalog';toggleFacet('source',b.dataset.sideSource);render();}
else if(b.dataset.view){if(b.dataset.view==='favorites'&&!preferencesReady)await loadPreferences();if(b.dataset.view==='plans')plans=await api('/api/plans');if(b.dataset.view==='samples')sampleData=await api('/api/samples');state.view=b.dataset.view;state.page=1;if(state.view==='favorites')state.kind=[];if(state.view==='catalog')switchKind('package');render();}else if(b.dataset.detail)detail(b.dataset.detail);else if(b.hasAttribute('data-close'))$('#modal').close();else if(b.dataset.image){$('#detailPhoto').innerHTML=`<img src="${esc(b.dataset.image)}" data-gallery-record="${esc(b.dataset.imageRecord)}" alt="原表包材图片"><span class="image-label">${esc(b.dataset.imageLabel)}</span>${imageCount(records.find(r=>r.id===b.dataset.imageRecord)||{})}`;if($('#originalImageLink')){$('#originalImageLink').href=b.dataset.image;$('#originalImageLink').hidden=false;}}else if(b.dataset.favorite){if(!preferencesReady)await loadPreferences();const id=b.dataset.favorite;const next=prefs.favorites.includes(id)?prefs.favorites.filter(v=>v!==id):[...prefs.favorites,id];await api('/api/preferences',{favorites:next});prefs.favorites=next;render();if($('#modal').open)detail(id);toast(next.includes(id)?'已收藏':'已取消收藏');}else if(b.dataset.page&&!b.disabled){updateCatalogPage(b.dataset.page,{focus:b.dataset.pageControl||'current'});}else if(b.dataset.register){const id=b.dataset.register;modal('登记实物样品',`<div class="note">仅在实际收到样品后登记。每件需要独立借还的实物使用一个编号。</div><form id="registerForm" data-id="${esc(id)}"><div class="form-grid" style="margin-top:20px">${inputField('实物样品编号','id')}${inputField('存放位置（柜／层／格）','location')}${inputField('样品状况','condition','text','完好')}</div><p class="form-error" role="alert"></p><div class="dialog-foot"><button type="button" class="btn" data-close>取消</button><button class="btn primary">保存实物档案</button></div></form>`);}else if(b.dataset.sample)sampleForm(b.dataset.sample,b.dataset.op);else if(b.dataset.history){const history=await api('/api/samples/'+encodeURIComponent(b.dataset.history)+'/history');modal('实物流转记录',history.map(v=>`<div class="link-item"><b>${esc({register:'登记实物',lend:'借出',return:'归还',consumed:'测试耗用',sent:'寄给客户'}[v.action]||v.action)}</b><p class="sub">${esc(v.created)} · ${esc(v.actor)}</p><div class="raw">${esc(Object.entries(JSON.parse(v.details)).map(([k,value])=>`${({borrower:'借用人',due:'预计归还',location:'位置',condition:'状况',note:'说明',id:'编号',record_id:'资料编号'}[k]||k)}：${value}`).join('\n'))}</div></div>`).join('')||'暂无记录');}else if(b.dataset.plan){const p=plans.find(v=>v.id===b.dataset.plan);modal(p.title,`<p class="sub">以下为方案保存时的资料快照。</p>${p.snapshot.map(r=>`<div class="panel"><h3><span data-i18n-skip>${esc(r.name)}</span></h3><div class="source-line">${esc(source(r))}</div>${quoteDetails(r)}${extraDetails(r)}</div>`).join('')}`);}else if(b.id==='logout'){await api('/api/logout',{});location.href='/login';}else{switch(b.dataset.action){case 'retry-catalog':await init();break;case 'retry-preferences':await loadPreferences();break;case 'browse-materials':$('#searchForm')?.scrollIntoView({behavior:reduceMotion?.matches?'auto':'smooth',block:'start'});$('#query')?.focus({preventScroll:true});break;case 'reset':clearImageSearch();resetProductFilters();state.query='';state.kind=state.view==='favorites'?[]:['package'];render();break;case 'layout':state.table=!state.table;render();break;case 'compare':compare();break;case 'clear-selected':state.selected=[];render();break;case 'export':exportRows(filtered());break;case 'save-plan':if(!state.selected.length)return toast('请先选择候选包材');modal('保存选型方案',`<form id="planForm"><div class="form-grid">${inputField('方案名称（客户／项目）','title')}<label class="field full">需求、数量与待确认事项<textarea name="note"></textarea></label></div><p class="sub">保存 ${state.selected.length} 条记录的当前快照。</p><p class="form-error" role="alert"></p><div class="dialog-foot"><button type="button" class="btn" data-close>取消</button><button class="btn primary">保存方案</button></div></form>`);break;}}}catch(err){toast(err.message);}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='pageSize'){const size=Number(el.value);updateCatalogPage(Math.floor((state.page-1)*state.pageSize/size)+1,{size,focus:'size'});}else if(el.dataset.filter&&facetKeys.includes(el.dataset.filter)){toggleFacet(el.dataset.filter,el.value);if(el.dataset.filter==='capacity')state.capacityBand=[];refreshFacet(el.dataset.filter,el.value);}else if(el.dataset.select){const id=el.dataset.select;if(el.checked){if(state.selected.length>=4){el.checked=false;return toast('一次最多对比4条记录');}state.selected.push(id);}else state.selected=state.selected.filter(v=>v!==id);render();}});
document.addEventListener('submit',async e=>{const f=e.target;if(f.id==='pageJumpForm'){e.preventDefault();updateCatalogPage(f.elements.page.value,{focus:'jump'});return;}if(!['searchForm','registerForm','sampleActionForm','planForm'].includes(f.id))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));if(f.id==='searchForm'){setCatalogQuery(d.query);render();return;}const btn=f.querySelector('button[type="submit"],button:not([type])');if(btn)btn.disabled=true;try{if(f.id==='registerForm'){d.record_id=f.dataset.id;await api('/api/samples',d);sampleData=await api('/api/samples');toast('实物样品已登记');}if(f.id==='sampleActionForm'){await api('/api/samples/'+encodeURIComponent(f.dataset.id)+'/'+f.dataset.op,d);sampleData=await api('/api/samples');toast('流转记录已保存');}if(f.id==='planForm'){await api('/api/plans',{...d,ids:state.selected});plans=await api('/api/plans');state.view='plans';toast('选型快照已保存');}$('#modal').close();render();}catch(err){f.querySelector('.form-error').textContent=err.message;}finally{if(btn)btn.disabled=false;}});
function applySiteSettings(){const v=catalog.settings||{};document.title=getLanguage()==='en'?'Yuanze Packaging Library · Internal selection':v.siteTitle||'源泽包材库 · 内部选型';$('#brandName').textContent=v.brandName||'源泽';$('#brandEnglish').textContent=v.englishName||'YUANZE PACKAGING';$('#companyName').textContent=v.companyName||'广州源泽药业有限公司';$('#footerCompany').textContent=v.companyName||'广州源泽药业有限公司';$('#footerNote').textContent=v.footerNote||'';$('#businessLink').hidden=v.showBusinessDemo===false;viewNames.catalog=v.catalogTitle||'包材选型库';$('#catalogNavLabel').textContent=viewNames.catalog;}
let catalogLoading=false;
async function init(){if(catalogLoading)return;catalogLoading=true;$('#main').innerHTML='<div class="empty" role="status">正在读取包材资料…</div>';try{session=await api('/api/session');catalog=await api('/api/catalog');if(!Array.isArray(catalog.records))throw Error('包材数据格式异常，请稍后重试。');records=catalog.records.map(r=>{const item={...r,name:text(r.name)||'名称待补'};item._uses=recordUses(item);item._sections=recordSections(item);item._sourceFile=text(r.source?.workbook||'');item._category=category(item);item._materials=materials(item);item._capacities=capacities(item);item._search=[item.productCode,item.id,item.name,item.searchText,item._sourceFile,item.bottleType,item.series,item.model,item.description,...(item.productDetails||[]).flatMap(d=>[d.label,d.value]),...item._uses,...item._sections.map(k=>sectionNames[k]),...Object.entries(item).filter(([k])=>k.endsWith('Raw')).map(([,v])=>text(v)),raw(item),supplier(item),quote(item),item._category,...item._materials,...item._capacities.map(v=>v+'ml')].map(text).join(' ');item._search=normalizeSearch(item._search+' '+[item._category,item.bottleType,...item._materials,...item._uses,...item._sections.map(k=>sectionNames[k])].map(value=>translateValue(value,'en')).join(' '));return item;});productCodeIndex=new Map(records.filter(r=>r.productCode).map(r=>[codeKey(r.productCode),r]));recordIdIndex=new Map(records.map(r=>[normalizeSearch(r.id).trim(),r]));applySiteSettings();$('#adminLink').hidden=session.role!=='admin';$('#account').dataset.i18nSkip='';$('#account').textContent=session.local?t('本机预览'):session.username;$('#logout').hidden=session.local;const requestedCode=new URLSearchParams(location.search).get('code');if(requestedCode)setCatalogQuery(requestedCode);render();loadPreferences().catch(()=>{});loadImageSearchStatus();}catch(err){$('#main').innerHTML=`<div class="panel load-error"><h2>暂时无法读取包材资料</h2><p role="alert">${esc(err.message)}</p><button type="button" class="btn primary" data-action="retry-catalog">重试加载</button>${err.status===401?' <a class="btn" href="/login">重新登录</a>':''}</div>`;}finally{catalogLoading=false;}}
init();
if(document.modelContext?.registerTool){const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});for(const tool of [{name:'search_packaging_catalog',description:'在已登录的内部包材库中查询名称、编号和规格原文，不修改业务数据。',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input.query!=='string'||Object.keys(input).some(k=>k!=='query'))throw Error('请提供查询文字');const lookup=numberLookup(input.query),matchers=searchMatchers(input.query);return records.filter(r=>lookup.active?r.id===lookup.record?.id:matchesText(r,matchers)).slice(0,20).map(r=>({id:r.id,productCode:r.productCode||'',name:r.name,source:source(r),quoteStatus:quote(r)?'有历史报价原文':'待询价'}));}},{name:'open_packaging_record',description:'在已登录页面打开指定包材询价记录的详情，仅改变页面。',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.id!=='string'||Object.keys(input).some(k=>k!=='id')||!records.some(r=>r.id===input.id))throw Error('记录不存在');detail(input.id);return {opened:input.id};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{});}catch{}}}

onLanguageChange(()=>{if(session.local)$('#account').textContent=t('本机预览');document.title=getLanguage()==='en'?'Yuanze Packaging Library · Internal selection':catalog.settings?.siteTitle||'源泽包材库 · 内部选型';});
